// Generated by scripts/gen-miniapp.ts (bun run gen:miniapp) from lib/actions/consistency. Do not edit.
/* The shape of the consistency table (rows.ts): small designs, what a visitor does to them, and what every host must
 * end up showing and sending. Plain data, so the rows can be written into the React Native kit's and the mini-program
 * kit's own test beds (scripts/gen-rn.ts, scripts/gen-miniapp.ts) and read there by their own runners. */

/* the design's action, as the kit's own types say it */
type VarValue = string | number | boolean;
type VarType = "text" | "number" | "bool" | "color";
type Action = Record<string, unknown>;
type ActionBody = Record<string, unknown>;

/** every host the table is run on */
export const HOSTS = ["interpreter", "preview", "webPrototype", "webProduct", "rn", "miniapp"] as const;
export type HostName = (typeof HOSTS)[number];

/** what a host is called in the docs */
export const HOST_TITLES: Record<HostName, string> = {
  interpreter: "解释器（lib/actions）",
  preview: "预览",
  webPrototype: "原型 Web",
  webProduct: "产品 Web",
  rn: "手机端套件（RN）",
  miniapp: "小程序套件",
};

/** A part of the design. Every part carries words of its own (`label`), unique in its design: that is how a step
 *  names what it taps and how a host's outcome says what is on show. */
export type PartSpec = {
  id: string;
  /** the screen it is on (the first when left out) */
  screen?: string;
  /** a button (the default), words, a text field, a dropdown menu (the words are its trigger's), a dialog */
  kind?: "button" | "text" | "field" | "menu" | "dialog";
  label: string;
  /** a menu's entries, a dialog's confirm button */
  items?: string[];
  action?: Action;
  /** the action is written into the document as it is, past the editor's own checks (calls nested deeper than it
   *  lets an author nest them) */
  unchecked?: boolean;
  /** hidden at the start */
  hidden?: boolean;
  /** the input fills this field of its form (`Item.field`) */
  field?: string;
};

export type ScreenSpec = { id: string; name: string; params?: string[]; auth?: "required" | "login" };

/** an operation of the contract: its query parameters, its body's fields (strings unless said; a form's inputs are
 *  labelled with their titles), the fields of its answer */
export type OperationSpec = {
  operationId: string;
  method?: "get" | "post";
  path: string;
  query?: string[];
  body?: Record<string, { title: string; type?: "string" | "number"; required?: boolean }>;
  returns?: Record<string, "string" | "number">;
};

export type Design = {
  screens: ScreenSpec[];
  parts: PartSpec[];
  vars?: { id: string; name: string; type: VarType; value: VarValue }[];
  api?: OperationSpec[];
  /** the operation that signs in */
  login?: string;
  /** forms, made the way the editor makes them (`make_form`): an input per body field (labelled with its title), then
   *  a submit button with these words, which submits the form; `ok` runs after a 2XX answer (its `then`), `fail` after
   *  any other (its `catch`) */
  forms?: { screen?: string; operationId: string; submit: string; ok?: ActionBody; fail?: ActionBody }[];
};

/** What the visitor and the back end do, one after another. Each step lets the host settle before the next. */
export type Step =
  /** a tap on the part with these words, on the screen on show */
  | { tap: string }
  /** words typed into the field with these words */
  | { type: string; value: string }
  /** The oldest call of this operation that is being held is answered (`status` 200 and `{}` unless said). Calls of the
   *  operations in `Row.hold` wait for this; every other call is answered at once. */
  | { answer: string; status?: number; body?: unknown; which?: "oldest" | "newest" }
  /** the host starts over: another scenario of the mocks, a restarted runtime */
  | { restart: true }
  /** the pointer comes over the part with these words; a host with no pointer taps it instead (docs/交互规则.md 触发方式) */
  | { hover: string }
  /** this many milliseconds pass */
  | { wait: number };

/** a call as the back end saw it: its operation and what it was given (query and JSON body fields together) */
export type SeenCall = { op: string; in: Record<string, unknown> };

/** What the host ends up with. Only what is given is compared. */
export type Expect = {
  /** the variables, by id */
  vars?: Record<string, VarValue>;
  /** whether the words are on show on the screen on show (or the overlay over it) */
  shown?: Record<string, boolean>;
  /** the snackbar on show, null for none */
  toast?: string | null;
  /** the screen on show (its id), under any overlay */
  screen?: string;
  /** the calls the back end received, in order; each compared on the fields given */
  calls?: SeenCall[];
};

export type Row = {
  id: string;
  /** what the row checks (docs/交互规则.md) */
  title: string;
  /** the section of docs/交互规则.md, and of the review report where it comes from */
  ref: string;
  design: Design;
  /** the operations whose calls wait for an `answer` step */
  hold?: string[];
  /** how the back end answers what it is not told to hold: by operation, `{ status: 200, body: {} }` otherwise */
  answers?: Record<string, { status: number; body?: unknown }>;
  steps: Step[];
  expect: Expect;
  /** Hosts that do not do this today, each with why (and the report's section): the divergences the hosts' move onto
   *  lib/actions burns down. A host listed here that passes fails the table, so a fix takes its entry out. */
  known?: Partial<Record<HostName, string>>;
};

/** what a host showed at the end, to compare with `Expect` */
export type Observed = {
  vars: Record<string, VarValue>;
  /** every piece of words on show (the screen on show and any overlay over it) */
  words: string[];
  toast: string | null;
  screen: string;
  calls: SeenCall[];
};

/** a row as a kit's runner has it (lib/actions/consistency/kits.ts): no design, which the kit's printer has printed
 *  already, but its variables' ids and its screens' ids by the keys the printed app knows them by */
export type KitRow = Omit<Row, "design"> & { vars: string[]; screens: Record<string, string> };
